/**
 * magnet-flow.js — the visual conversation flow builder for client-saas /magnets.
 *
 * A dedicated modal (opened from a magnet card's "Flow" button) that renders the magnet's
 * conversation as a vertical canvas of connected node-cards — one per step, type-colored,
 * showing a live preview of the prompt + choices. Cards drag-to-reorder (native HTML5 DnD
 * with drop indicators); click a card to expand it into an inline editor; add steps from a
 * type palette. Saves the whole flow via PATCH { steps } → mag_macro_steps.
 *
 * Linear model (matches the SDK): reorder / add / edit / delete. Any existing `goto` branch
 * on an option is preserved across a round-trip (free-form visual branching is future work).
 */

import AuthController from '../services/AuthController.js';
import PubSub from 'pubsub-js';
import AppBroadcast from '../../../../shared/appBroadcast.js';
import { LEAD_CAPTURE_FIELDS, STEP_TYPES } from '@sse/shared';

const ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ESC[c]);
const toast = (message, type = 'info') => { try { PubSub.publish(AppBroadcast.UI_TOAST, { message, type }); } catch { /* no-op */ } };
const apiBase = () => AuthController.getConfig?.().BASE_URL || '';

// step type → node icon + accent color (client-only presentation; the value set and
// label come from the shared STEP_TYPES, so magnets.js's server-side validation and
// this editor's dropdown can't drift the way they already did once — same shape of
// bug as LEAD_CAPTURE_FIELDS/KNOWN_FIELDS and the support_topics defaults).
// darkColor: the light-mode `color` values are chosen to read on --color-bg white;
// 5 of the 7 measure under the 4.5:1 AA minimum against --color-bg dark (#091620) —
// e.g. single_select's #0072BA is ~3.6:1. darkColor is a brightened per-type
// replacement (computed, not eyeballed) used only when [data-theme="dark"].
const TYPE_ICON_COLOR = {
  single_select: { icon: 'quiz', color: '#0072BA', darkColor: '#38BDF8' },
  multi_select: { icon: 'checklist', color: '#0E6BA8', darkColor: '#22D3EE' },
  scheduler: { icon: 'event', color: '#915E8B', darkColor: '#E879F9' },
  text: { icon: 'short_text', color: '#5B54C6', darkColor: '#A78BFA' },
  email: { icon: 'mail', color: '#0E8F86', darkColor: '#2DD4BF' },
  phone: { icon: 'call', color: '#2E8B57', darkColor: '#4ADE80' },
  message: { icon: 'chat', color: '#B4791F', darkColor: '#FBBF24' },
};
const TYPE_META = {};
STEP_TYPES.forEach((t) => {
  TYPE_META[t.value] = { label: t.label, ...(TYPE_ICON_COLOR[t.value] || { icon: 'quiz', color: '#0072BA', darkColor: '#38BDF8' }) };
});
const TYPE_ORDER = STEP_TYPES.map((t) => t.value);
// Editable per-CTA routes (shown only when the magnet has that CTA). chat = mag_macro_steps.
const ROUTE_LABEL = { chat: 'Chat / default', book: 'Book (scheduler)', support: 'Support (intake)' };
const meta = (t) => {
  const m = TYPE_META[t] || TYPE_META.single_select;
  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
  return isDark ? { ...m, color: m.darkColor } : m;
};
const needsOptions = (v) => v === 'single_select' || v === 'multi_select';
const needsField = (v) => v !== 'message';
const needsSchedule = (v) => v === 'scheduler';
// Only a message step can be terminal (matches the SDK: renderTerminal() only ever
// fires from the `type === 'message'` branch of advance()).
const canBeTerminal = (v) => v === 'message';
// scheduler has no dedicated real column to default to (see the Saves-to dropdown
// below) — left blank so the person building the flow has to pick one explicitly,
// same as the "choose which field this answer saves to" validation already requires.
const defaultFieldFor = (v) => (v === 'email' ? 'email' : v === 'phone' ? 'phone' : '');
const defaultSchedule = () => ({ meeting_label: '', start: '09:00', end: '17:00', mins: 30, days: 14 });
// step_config is a shared per-step bag, and this editor only owns PART of it. These are
// the keys the scheduler card renders; everything else in there belongs to a feature the
// flow editor has no UI for and must survive an edit round-trip untouched:
//   terminal / cta        — a message step's endpoint card + outbound link (SDK renderTerminal)
//   placeholder, optional — input-step knobs (SDK renderInput)
//   skip_if_prefilled     — auto-advance when the host already supplied the column (SDK advance)
// Treating the bag as scheduler-only is what silently deleted authored CTAs on save.
const SCHEDULE_KEYS = ['meeting_label', 'start', 'end', 'mins', 'days'];
// The terminal card now HAS a UI (below), so these are owned by this editor too — but
// shedding them still has to leave the rest of the bag alone, same as SCHEDULE_KEYS.
const TERMINAL_KEYS = ['terminal', 'cta'];
// Shed the named keys, keep the rest. null (not {}) when nothing is left, so an
// ordinary step still serializes without an empty step_config riding along.
function configWithout(cfg, dropKeys) {
  const out = {};
  Object.keys(cfg && typeof cfg === 'object' ? cfg : {}).forEach((k) => {
    if (!dropKeys.includes(k)) out[k] = cfg[k];
  });
  return Object.keys(out).length ? out : null;
}
function configWithoutSchedule(cfg) {
  return configWithout(cfg, SCHEDULE_KEYS);
}
// icons the SDK can actually render (must match its MPATH registry); '' = none. Friendly labels.
const OPTION_ICONS = [
  ['', 'No icon'], ['event', 'Calendar'], ['schedule', 'Clock'], ['mail', 'Email'], ['sms', 'Text'],
  ['phone', 'Phone'], ['chat', 'Chat'], ['description', 'Document'], ['help', 'Question'], ['place', 'Location'],
  ['person', 'Person'], ['bolt', 'Quick'], ['check_circle', 'Check'], ['star', 'Star'], ['home', 'Home'], ['build', 'Service'],
];

function hexToRgba(hex, a) {
  const m = /^#?([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(String(hex || '').trim());
  if (!m) return `rgba(0,114,186,${a})`;
  return `rgba(${parseInt(m[1], 16)},${parseInt(m[2], 16)},${parseInt(m[3], 16)},${a})`;
}

