// ── working state (one editor open at a time) ────────────────────────────────
let stepsModel = [];
let openUid = null;
let uidSeq = 0;
let dragUid = null;
let dropInfo = null;
// Hoisted so the exported validate/save/preview helpers (called from the host edit
// modal's footer) reach the same working model the mounted editor mutates.
let currentRoute = 'chat';
let flowRouteModels = {};
let flowRouteKeys = [];
let flowMagnet = null;
let flowOnDirty = null;
// The magnet's modified_tz as of when the editor was opened (D1) — compared against
// the current value right before saving, so two tabs (or two people) editing the same
// magnet get a warning instead of one silently clobbering the other. Minimum viable
// version: a warn-before-overwrite, not real optimistic-concurrency locking (that would
// need the PATCH endpoint itself to reject a stale write, not just the client to ask
// first) — good enough to catch the common case (a stray duplicate tab, a teammate
// editing at the same time) without the larger change a hard server-side guard needs.
let flowLoadedModifiedTz = '';
const uid = () => 'f' + (++uidSeq);

function blankStep(type = 'single_select') {
  return {
    _uid: uid(),
    id: '', // assigned at save (stable numbering; preserves goto targets)
    step_type: type,
    step_prompts: [''],
    step_options: needsOptions(type) ? [{ label: '', goto: '', icon: '' }, { label: '', goto: '', icon: '' }] : [],
    step_columns: defaultFieldFor(type) ? [defaultFieldFor(type)] : [],
    step_description: '',
    step_config: needsSchedule(type) ? defaultSchedule() : null,
  };
}

// One raw step array → an editable model (adds _uid, normalizes shapes).
function modelFromSteps(src) {
  return (Array.isArray(src) ? src : []).map((s) => ({
    _uid: uid(),
    id: s.id != null ? String(s.id) : '',
    step_type: TYPE_META[s.step_type] ? s.step_type : 'single_select',
    step_prompts: Array.isArray(s.step_prompts) ? s.step_prompts.map(String) : [],
    step_options: (Array.isArray(s.step_options) ? s.step_options : []).map((o) => ({
      label: o && o.label != null ? String(o.label) : '',
      goto: o && o.goto != null ? String(o.goto) : '',
      icon: o && o.icon != null ? String(o.icon) : '',
    })),
    step_columns: Array.isArray(s.step_columns) ? s.step_columns.map(String) : [],
    step_description: s.step_description != null ? String(s.step_description) : '',
    // Scheduler steps get the defaults merged underneath whatever was authored; every
    // other type keeps its bag verbatim. (Merging defaultSchedule() in unconditionally
    // stamped five dead scheduler keys onto e.g. a message step's { terminal, cta }.)
    step_config: needsSchedule(s.step_type)
      ? { ...defaultSchedule(), ...(s.step_config && typeof s.step_config === 'object' ? s.step_config : {}) }
      : ((s.step_config && typeof s.step_config === 'object') ? { ...s.step_config } : null),
  }));
}

// The shared name→email capture tail the SDK appends to the built-in book/support routes.
function captureTailModel() {
  return [
    { _uid: uid(), id: '', step_type: 'text', step_prompts: ['Great, and your name?'], step_options: [], step_columns: ['first_name'], step_description: '', step_config: null },
    { _uid: uid(), id: '', step_type: 'email', step_prompts: ['The best email to reach you?'], step_options: [], step_columns: ['email'], step_description: '', step_config: null },
  ];
}

// Seed a book/support route the FIRST time it's opened, mirroring the SDK's built-in defaults
// (support options come from the magnet's Support CTA config when it has any).
function seedRouteModel(route, magnet) {
  if (route === 'book') {
    // step_columns intentionally empty — 'preferred_time' isn't a real m5mLead field, so the
    // seed used to point at a value the dropdown (and the capture endpoint) don't recognize.
    // Left blank, the existing "choose which field this answer saves to" validation makes the
    // person setting up Book pick a real one (Notes / description is the natural choice).
    return [{ _uid: uid(), id: '', step_type: 'scheduler', step_prompts: ['When works best for you?'], step_options: [], step_columns: [], step_description: '', step_config: defaultSchedule() }, ...captureTailModel()];
  }
  if (route === 'support') {
    const supp = (magnet.actions || []).find((a) => a && a.type === 'support');
    const cfgOpts = (supp && supp.config && Array.isArray(supp.config.options)) ? supp.config.options : [];
    const options = (cfgOpts.length ? cfgOpts.map((o) => ({ label: (o && o.label) || String(o), goto: '', icon: (o && o.icon) || '' }))
      : ['Sales enquiry', 'Support', 'Billing', 'Something else'].map((l) => ({ label: l, goto: '', icon: '' })));
    // step_columns intentionally empty, same reasoning as the Book scheduler above —
    // 'support_topics' isn't a real m5mLead field or a capture-endpoint-recognized one.
    // What Support should save to by default (if anything) is a product decision still
    // to be made, not something to guess at here; the dropdown forces an explicit real
    // choice in the meantime.
    return [{ _uid: uid(), id: '', step_type: 'multi_select', step_prompts: ['How can we help you today?'], step_options: options, step_columns: [], step_description: 'Select all that apply', step_config: null }, ...captureTailModel()];
  }
  return [blankStep('single_select')];
}

// Build the working model for a route: authored steps if present, else the seed (book/support)
// or a blank first step (chat).
function loadRouteModel(route, magnet) {
  const authored = route === 'chat' ? magnet.steps : (magnet.routes && magnet.routes[route]);
  const model = modelFromSteps(authored);
  if (model.length) return model;
  return route === 'chat' ? [blankStep('single_select')] : seedRouteModel(route, magnet);
}

// keep options/field/config in sync with a step's type after a type change
function reconcileStep(step) {
  if (needsOptions(step.step_type)) {
    if (!step.step_options.length) step.step_options = [{ label: '', goto: '', icon: '' }, { label: '', goto: '', icon: '' }];
  } else {
    step.step_options = [];
  }
  if (needsField(step.step_type)) {
    if (!step.step_columns.length && defaultFieldFor(step.step_type)) step.step_columns = [defaultFieldFor(step.step_type)];
  } else {
    step.step_columns = [];
  }
  // A type change sheds the OTHER type's knobs, not the whole bag: dropping to null here
  // meant one mis-click on the type dropdown (even undone immediately) permanently deleted
  // an authored terminal CTA. Leaving an inert key behind is the cheaper mistake.
  step.step_config = needsSchedule(step.step_type)
    ? { ...defaultSchedule(), ...(step.step_config || {}) }
    : configWithoutSchedule(step.step_config);
}

